#!/usr/bin/env python3
# Full 7z header parser (for analyzing reference binary outputs)
import sys, struct, lzma

data = open(sys.argv[1], 'rb').read()
assert data[:6] == b'7z\xbc\xaf\x27\x1c'
nh_off, nh_size, nh_crc = struct.unpack('<QQI', data[12:32])

def read_uint(b, p):
    f = b[p]
    if f < 0x80: return f, p+1
    value = 0
    mask = 0x80
    i = 0
    while True:
        value |= b[p+1+i] << (8*i)
        mask >>= 1
        if not (f & mask):
            break
        i += 1
    high = f & (mask - 1)
    value += high << (8*(i+1))
    return value, p+2+i

def read_bitmask(b, p, n):
    res = []
    cur = 0
    for i in range(n):
        if i % 8 == 0:
            cur = b[p]; p += 1
        res.append((cur >> (7 - i%8)) & 1)
    return res, p

CODECS = {b'\x00':'Copy', b'\x03\x01\x01':'LZMA', b'\x21':'LZMA2', b'\x04\x02\x02':'BZip2', b'\x03\x04\x01':'PPMD', b'\x06\xf1\x07\x01':'7zAES', b'\x03\x03\x01\x03':'BCJ', b'\x03':'Delta'}

class Folder:
    pass

def parse_folder(b, p):
    f = Folder()
    f.coders = []
    nc, p = read_uint(b, p)
    tot_in = tot_out = 1
    for _ in range(nc):
        fl = b[p]; p += 1
        idsz = fl & 0xF
        cid = b[p:p+idsz]; p += idsz
        nin = nout = 1
        if fl & 0x10:
            nin, p = read_uint(b, p); nout, p = read_uint(b, p)
            tot_in, tot_out = nin, nout
        props = b''
        if fl & 0x20:
            psz, p = read_uint(b, p); props = b[p:p+psz]; p += psz
        f.coders.append((cid, props, nin, nout))
    f.binds = []
    for _ in range(tot_out - 1):
        bi, p = read_uint(b, p); bo, p = read_uint(b, p)
        f.binds.append((bi, bo))
    f.packidx = []
    npi = tot_in - len(f.binds) - 1
    for _ in range(npi):
        if npi == 1 and tot_in == 1:
            f.packidx.append(0)
        else:
            v, p = read_uint(b, p); f.packidx.append(v)
    return f, p

def parse_streams(b, p):
    info = {'folders': [], 'packsizes': [], 'unpacksizes': [], 'subsizes': [], 'numsub': []}
    while True:
        i = b[p]; p += 1
        if i == 0: return p, info
        if i == 6:
            info['packpos'], p = read_uint(b, p)
            ns, p = read_uint(b, p)
            while True:
                i2 = b[p]; p += 1
                if i2 == 0: break
                if i2 == 9:
                    for _ in range(ns):
                        v, p = read_uint(b, p); info['packsizes'].append(v)
                elif i2 == 0xA:
                    alldef = b[p]; p += 1
                    if alldef:
                        info['packcrcs'] = [struct.unpack('<I', b[p+4*k:p+4*k+4])[0] for k in range(ns)]; p += 4*ns
                    else:
                        bits, p = read_bitmask(b, p, ns)
                        info['packcrcs'] = []
                        for k in range(ns):
                            if bits[k]:
                                info['packcrcs'].append(struct.unpack('<I', b[p:p+4])[0]); p += 4
                            else: info['packcrcs'].append(None)
                else:
                    sz, p = read_uint(b, p); p += sz
        elif i == 7:
            assert b[p] == 0xB; p += 1
            nf, p = read_uint(b, p)
            ext = b[p]; p += 1
            for _ in range(nf):
                fo, p = parse_folder(b, p)
                info['folders'].append(fo)
            assert b[p] == 0xC; p += 1
            for fo in info['folders']:
                tot = 0
                for c in fo.coders: tot += c[3]
                # unpack size per out stream... actually one value per coder out stream total
                v, p = read_uint(b, p)
                info['unpacksizes'].append(v)
            while True:
                i2 = b[p]; p += 1
                if i2 == 0: break
                if i2 == 0xA:
                    alldef = b[p]; p += 1
                    n = len(info['folders'])
                    if alldef:
                        info['foldercrcs'] = [struct.unpack('<I', b[p+4*k:p+4*k+4])[0] for k in range(n)]; p += 4*n
                    else:
                        bits, p = read_bitmask(b, p, n)
                        info['foldercrcs'] = []
                        for k in range(n):
                            if bits[k]:
                                info['foldercrcs'].append(struct.unpack('<I', b[p:p+4])[0]); p += 4
                            else: info['foldercrcs'].append(None)
                else:
                    sz, p = read_uint(b, p); p += sz
        elif i == 8:
            nfo = len(info['folders'])
            while True:
                i2 = b[p]; p += 1
                if i2 == 0: break
                if i2 == 0xD:
                    for k in range(nfo):
                        v, p = read_uint(b, p); info['numsub'].append(v)
                elif i2 == 9:
                    tot = sum(info['numsub']) if info['numsub'] else 0
                    for k in range(tot - nfo):
                        v, p = read_uint(b, p); info['subsizes'].append(v)
                elif i2 == 0xA:
                    nd = 0
                    for k in range(nfo):
                        ns2 = info['numsub'][k] if info['numsub'] else 1
                        if not (ns2 == 1 and info.get('foldercrcs') and info['foldercrcs'][k] is not None):
                            nd += ns2
                    alldef = b[p]; p += 1
                    crcs = []
                    if alldef:
                        for k in range(nd):
                            crcs.append(struct.unpack('<I', b[p:p+4])[0]); p += 4
                    else:
                        bits, p = read_bitmask(b, p, nd)
                        for k in range(nd):
                            if bits[k]:
                                crcs.append(struct.unpack('<I', b[p:p+4])[0]); p += 4
                            else: crcs.append(None)
                    info['subcrcs'] = crcs
                else:
                    sz, p = read_uint(b, p); p += sz
        else:
            raise Exception(f"unknown streams id {i}")

def parse_files(b, p):
    nf, p = read_uint(b, p)
    props = []
    while True:
        i = b[p]; p += 1
        if i == 0: return p, nf, props
        sz, p = read_uint(b, p)
        content = b[p:p+sz]
        props.append((i, content))
        p += sz

def describe_header(b):
    p = 0
    i = b[p]; p += 1
    assert i == 1
    folders = []
    while True:
        i = b[p]; p += 1
        if i == 0: break
        if i == 4:
            p, si = parse_streams(b, p)
            folders = si['folders']
            print(" MainStreams:", {k: v for k, v in si.items() if k != 'folders'})
            for fi, fo in enumerate(folders):
                print(f"  Folder{fi}: coders={[(CODECS.get(c[0], c[0].hex()), c[1].hex()) for c in fo.coders]} binds={fo.binds} packidx={fo.packidx}")
        elif i == 3:
            p, si = parse_streams(b, p)
            print(" AdditionalStreams")
        elif i == 5:
            p, nf, props = parse_files(b, p)
            print(f" FilesInfo NumFiles={nf}")
            for pid, content in props:
                name = {0xE:'EmptyStream',0xF:'EmptyFile',0x10:'Anti',0x11:'Name',0x12:'CTime',0x13:'ATime',0x14:'MTime',0x15:'WinAttrib',0x16:'Comment',0x18:'StartPos',0x19:'Dummy19'}.get(pid, hex(pid))
                if pid == 0x11:
                    ext = content[0]
                    names = content[1:].decode('utf-16-le').split('\x00')[:-1]
                    print(f"   Name ext={ext}: {names}")
                elif pid in (0x12, 0x13, 0x14):
                    alldef = content[0]
                    print(f"   {name}: alldef={alldef} rest={content[1:].hex()}")
                elif pid == 0x15:
                    print(f"   WinAttrib: {content.hex()}")
                else:
                    print(f"   {name}: {content.hex()}")
        else:
            raise Exception(f"unknown header id {i}")

hdr = data[32+nh_off:32+nh_off+nh_size]
p = 0
i = hdr[p]; p += 1
if i == 0x17:
    p, si = parse_streams(hdr, p)
    fo = si['folders'][0]
    cid, props = fo.coders[0][0], fo.coders[0][1]
    print(f"[EncodedHeader LZMA props={props.hex()} packpos={si['packpos']} packsize={si['packsizes']} usize={si['unpacksizes']}]")
    comp = data[32+si['packpos']:32+si['packpos']+si['packsizes'][0]]
    lc = props[0] % 9; lp = (props[0]//9)%5; pb = props[0]//45
    dsz = struct.unpack('<I', props[1:5])[0]
    filt = [{'id': lzma.FILTER_LZMA1, 'dict_size': dsz, 'lc': lc, 'lp': lp, 'pb': pb}]
    d = lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=filt)
    raw = d.decompress(comp)
    print(f" hdr LZMA: lc={lc} lp={lp} pb={pb} dict={dsz}")
    describe_header(raw)
else:
    describe_header(hdr)

